// Service pays invoices.
type Service struct {
	Store     *store.Store
	Gateway   Gateway
	Clock     clock.Clock
	Publisher Publisher // nil: no events

	mu       sync.Mutex
	charging map[invoiceKey]bool // the invoices a Pay is working on now
}

type invoiceKey struct{ org, invoice string }

// begin claims an invoice for a Pay; it is false when another Pay holds it.
func (s *Service) begin(k invoiceKey) bool {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.charging[k] {
		return false
	}
	if s.charging == nil {
		s.charging = map[invoiceKey]bool{}
	}
	s.charging[k] = true
	return true
}

func (s *Service) end(k invoiceKey) {
	s.mu.Lock()
	defer s.mu.Unlock()
	delete(s.charging, k)
}

// Pay charges an open invoice's total to paymentMethod, or to the customer's default payment method when it is empty, and
// marks the invoice paid. An invoice whose total is zero or less is marked paid without a charge. A declined charge is
// recorded as a failed payment and returned as a *DeclineError; when the gateway is unavailable nothing is recorded and the
// error wraps ErrUnavailable. While a Pay of the same invoice is under way, Pay returns ErrPaymentInProgress at once.
func (s *Service) Pay(ctx context.Context, orgID, invoiceID, paymentMethod string) (store.Invoice, store.Payment, error) {
	k := invoiceKey{orgID, invoiceID}
	if !s.begin(k) {
		return store.Invoice{}, store.Payment{}, ErrPaymentInProgress
	}
	defer s.end(k)
	inv, ok := s.Store.Invoice(orgID, invoiceID)

